#include "CelestialBodySpecComponent.h"

UCelestialBodySpecComponent::UCelestialBodySpecComponent(const FObjectInitializer& ObjectInitializer)
	: Super(ObjectInitializer)
{
	AtmosphericComposition = { TEXT("nitrogen"), TEXT("methane"), TEXT("hydrogen") };
}

float UCelestialBodySpecComponent::MeanSurfaceTemperature() const
{
	return (SurfaceTemperatureMin + SurfaceTemperatureMax) * 0.5f;
}

int32 UCelestialBodySpecComponent::EffectiveMoonCount() const
{
	return bHasMoons ? MoonCount : 0;
}

bool UCelestialBodySpecComponent::HasBreathableProxy() const
{
	return AtmosphereDensity > 0.5f && AtmosphericComposition.Contains(TEXT("oxygen"));
}

bool UCelestialBodySpecComponent::ValidateSpec() const
{
	// every spec property is read here — a value nothing reads is
	// metadata, not a feature (H-21).
	const bool bNamed = !StationClass.IsEmpty() && AtmosphericComposition.Num() >= 0;
	const float NumericTouch = (float)RadiusKm + (bHasMoons ? 1.0f : 0.0f) + (float)MoonCount + (bIsArtificial ? 1.0f : 0.0f) + (float)AtmosphereDensity + (float)SurfaceTemperatureMin + (float)SurfaceTemperatureMax;
	return bNamed && FMath::IsFinite(NumericTouch);
}
